#include "coh_class_named.h"
#include <string.h>
typedef struct{const void*p;size_t n;}Span;
static int valid(Span a){return a.p?(uintptr_t)a.p<=UINTPTR_MAX-a.n:!a.n;}
static int overlap(Span a,Span b){return a.n&&b.n&&(uintptr_t)a.p<(uintptr_t)b.p+b.n&&(uintptr_t)b.p<(uintptr_t)a.p+a.n;}
static unsigned fold(unsigned c){return c>='A'&&c<='Z'?c+32:c;}
static int equal(CohBytes a,CohBytes b){if(a.size!=b.size)return 0;for(size_t i=0;i<a.size;i++)if(fold(a.data[i])!=fold(b.data[i]))return 0;return 1;}
static uint32_t word(const uint8_t*p){return(uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static CohStatus charge(Span*spans,unsigned count,size_t budget,size_t retained){if(!budget||budget>COH_CLASS_NAMED_RAM_MAX)return COH_INVALID;size_t used=COH_CLASS_NAMED_STACK_RESERVE;for(unsigned i=0;i<count;i++){if(!valid(spans[i]))return COH_INVALID;for(unsigned j=0;j<i;j++)if(overlap(spans[i],spans[j]))return COH_INVALID;if(spans[i].n>budget||used>budget-spans[i].n)return COH_LIMIT;used+=spans[i].n;}return retained>budget-used?COH_LIMIT:COH_OK;}
static CohStatus dictionary(const CohClassDictionary*d){return d->raw_schema_validated&&d->input_lease&&d->input.data&&d->input.size&&d->input.size<=COH_CLASS_INPUT_MAX&&d->count<=COH_CLASS_MAX&&d->modtable_count<=COH_CLASS_TABLES_MAX&&d->text_count<=COH_CLASS_TEXTS_MAX&&d->text_bytes<=COH_CLASS_TEXT_BYTES_MAX?COH_OK:COH_STATE;}
static CohStatus row(const CohClassDictionary*d,unsigned index,CohBytes*name,CohBytes*values){if(index>=d->modtable_count)return COH_STATE;CohClassModTable m=d->modtables[index];if(m.owner>=d->count||m.name_text>=d->text_count||m.record.begin>m.record.end||m.record.end>d->input.size||m.record.end-m.record.begin<12)return COH_STATE;CohClassText t=d->texts[m.name_text];if(t.owner!=m.owner||t.table!=4||t.row!=m.row||t.field||t.element||t.offset>=d->text_bytes||t.size>=d->text_bytes-t.offset||d->text[t.offset+t.size])return COH_STATE;*name=(CohBytes){(const uint8_t*)d->text+t.offset,t.size};if(name->size>=260)return COH_UNSUPPORTED;for(size_t j=0;j<name->size;j++)if(!name->data[j]||name->data[j]>127)return COH_UNSUPPORTED;const uint8_t*p=d->input.data+m.record.begin;if(word(p)!=m.record.end-m.record.begin-4)return COH_STATE;size_t n=(size_t)p[4]|(size_t)p[5]<<8,at=6+n+(4-(n+2)%4)%4;if(n!=name->size||at>m.record.end-m.record.begin-4||memcmp(p+6,name->data,n))return COH_STATE;uint32_t count=word(p+at);at+=4;if(count>4096||count!=(m.record.end-m.record.begin-at)/4||m.record.end-m.record.begin-at!=(size_t)count*4)return COH_STATE;*values=(CohBytes){p+at,(size_t)count*4};for(unsigned j=0;j<count;j++)if((word(values->data+4*j)&UINT32_C(0x7f800000))==UINT32_C(0x7f800000))return COH_UNSUPPORTED;return COH_OK;}
CohStatus coh_class_named_prepare(const CohClassDictionary*d,CohClassNamedDictionary*out,size_t budget,size_t retained){if(!d||!out)return COH_INVALID;Span spans[]={{d,sizeof(*d)},{out,sizeof(*out)}};CohStatus status=charge(spans,2,budget,retained);if(status!=COH_OK)return status;if(dictionary(d)!=COH_OK)return COH_STATE;Span all[]={{d,sizeof(*d)},{out,sizeof(*out)},{d->input.data,d->input.size}};status=charge(all,3,budget,retained);if(status!=COH_OK)return status;size_t work=COH_CLASS_NAMED_COMPARISON_WORK_MAX;for(unsigned i=0;i<d->modtable_count;i++){CohBytes name,values;status=row(d,i,&name,&values);if(status!=COH_OK)return status;for(unsigned j=0;j<i;j++){if(d->modtables[j].owner==d->modtables[i].owner){/* Earlier rows were fully checked once; immutable copied keys require no
 * repeat float/record scan or repeat key validation. Charge worst-case string
 * work BEFORE equality: one length comparison even for unequal lengths. */CohClassText t=d->texts[d->modtables[j].name_text];CohBytes prior={(const uint8_t*)d->text+t.offset,t.size};size_t cost=1+(name.size==prior.size?name.size:0);if(cost>work)return COH_LIMIT;work-=cost;if(equal(name,prior))return COH_STATE;}}}CohClassNamedDictionary candidate;memset(&candidate,0,sizeof(candidate));candidate.source=d;candidate.source_lease=d->input_lease;memcpy(candidate.source_sha256,d->input_sha256,32);candidate.table_count=d->modtable_count;candidate.validated=1;*out=candidate;return COH_OK;}
CohStatus coh_class_named_get(const CohClassNamedDictionary*owner,uint32_t which,CohBytes name,uint32_t index,CohClassNamedValue*out,size_t budget,size_t retained){if(!owner||!out||!name.data||name.size>=260)return COH_INVALID;Span base[]={{owner,sizeof(*owner)},{out,sizeof(*out)},{name.data,name.size}};CohStatus status=charge(base,3,budget,retained);if(status!=COH_OK)return status;if(!owner->validated||!owner->source)return COH_STATE;const CohClassDictionary*d=owner->source;if(!valid((Span){d,sizeof(*d)}))return COH_INVALID;if(dictionary(d)!=COH_OK||owner->source_lease!=d->input_lease||owner->table_count!=d->modtable_count||memcmp(owner->source_sha256,d->input_sha256,32)||which>=d->count)return COH_STATE;Span all[]={{owner,sizeof(*owner)},{out,sizeof(*out)},{name.data,name.size},{d,sizeof(*d)},{d->input.data,d->input.size}};status=charge(all,5,budget,retained);if(status!=COH_OK)return status;for(size_t i=0;i<name.size;i++)if(!name.data[i]||name.data[i]>127)return COH_UNSUPPORTED;if(index>INT32_MAX)return COH_UNSUPPORTED;CohClassNamedValue candidate;memset(&candidate,0,sizeof(candidate));candidate.class_index=which;candidate.requested_index=index;candidate.table_index=UINT32_MAX;candidate.applied_index=UINT32_MAX;candidate.value_word=UINT32_C(0x3f800000);for(unsigned i=0;i<d->modtable_count;i++){if(d->modtables[i].owner==which){CohBytes key,values;status=row(d,i,&key,&values);if(status!=COH_OK)return status;if(equal(name,key)){uint32_t count=(uint32_t)(values.size/4);if(!count)return COH_UNSUPPORTED;candidate.found=1;candidate.table_index=i;candidate.applied_index=index<count?index:count-1;candidate.value_word=word(values.data+4*candidate.applied_index);break;}}}*out=candidate;return COH_OK;}
